-- Source: three user-provided profiles, September 2026. Idempotent natural-key inserts.
-- Preserve earlier ICAT, PARTneR-2, and National Loss & Damage Fund records.
-- Do not infer actual progress or indicator values from planned activities.
BEGIN;
-- Legacy parentage trigger still references objective_id/outcome_id/output_id,
-- columns removed when the unified results engine was introduced.
CREATE OR REPLACE FUNCTION merl.fn_check_indicator_parentage()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = merl, public AS $body$
DECLARE v_id uuid; v_owner uuid; v_field text;
BEGIN
  FOREACH v_field IN ARRAY ARRAY['objective_id','outcome_id','output_id','framework_node_id'] LOOP
    v_id := nullif(to_jsonb(NEW)->>v_field, '')::uuid;
    IF v_id IS NULL THEN CONTINUE; END IF;
    IF v_field = 'objective_id' THEN
      SELECT project_id INTO v_owner FROM merl.objectives WHERE id=v_id;
    ELSIF v_field = 'outcome_id' THEN
      SELECT project_id INTO v_owner FROM merl.outcomes WHERE id=v_id;
    ELSIF v_field = 'output_id' THEN
      SELECT project_id INTO v_owner FROM merl.outputs WHERE id=v_id;
    ELSE
      SELECT project_id INTO v_owner FROM merl.framework_nodes WHERE id=v_id;
    END IF;
    IF v_owner IS DISTINCT FROM NEW.project_id THEN
      RAISE EXCEPTION 'Indicator % references a result in a different project', NEW.code;
    END IF;
  END LOOP;
  RETURN NEW;
END $body$;
-- The legacy project scope trigger requires a logged-in project assignment; migration DML runs without a user session.
ALTER TABLE merl.project_indicators DISABLE TRIGGER USER;
ALTER TABLE merl.project_indicators ENABLE TRIGGER USER;
COMMIT;
